/**
 * uv.ts — UV в метрах.
 *
 * Половина убедительности процедурного материала держится не на самом рисунке,
 * а на его РАЗМЕРЕ. Кирпич должен быть кирпичом на любой стене: и на печной
 * щеке в полметра, и на дымоходе в три. Развёртка по умолчанию этого не даёт -
 * `BoxGeometry` кладёт на каждую грань UV от 0 до 1 независимо от габарита,
 * поэтому на маленькой детали кладка выходит мелкой крошкой, а на большой -
 * блоками по полстены.
 *
 * Лечение простое: UV умножается на РАЗМЕР ГРАНИ В МЕТРАХ и на общий масштаб
 * `s` - число тайлов на метр. Один и тот же материал с одним и тем же `s`
 * ложится по всей постройке одинаково, и подгонять `repeat` руками для каждой
 * детали больше не нужно.
 *
 * Отсюда же требование к самим картам: они обязаны стыковаться сами с собой.
 * Как только UV пошло за единицу, шов на стыке тайла становится видимой полосой
 * поперёк стены - см. договор о периоде в `noise.ts` и замер шва в проверке.
 */
import * as THREE from 'three';
/** Ось коробки, вдоль которой должно лечь волокно (V карты). */
export type Along = 'x' | 'y' | 'z';
/**
 * Развернуть коробку по метражу. Порядок граней у `BoxGeometry`:
 * +X, −X, +Y, −Y, +Z, −Z; у каждой свои две меры из (w, h, d).
 *
 * `s` - тайлов на метр. 0.5 значит «один тайл на два метра».
 *
 * `along` - вдоль какой оси коробки идёт волокно. У всех деревянных наборов
 * ядра волокно лежит по V, а штатная развёртка кладёт V на боковые грани
 * вверх: у царги кровати или столешницы волокно встало бы поперёк доски, и
 * глаз читает это мгновенно - доска будто из брусков. С `along` грань, у
 * которой названная ось идёт по U, разворачивается на четверть. Грани,
 * которым эта ось перпендикулярна (торцы доски), остаются как есть: там
 * волокно и должно смотреть в кадр торцом.
 */
export declare function boxUV(geo: THREE.BufferGeometry, w: number, h: number, d: number, s?: number, along?: Along): void;
/**
 * Круг целиком на одну карту: для радиальных наборов, у которых есть
 * середина, - торец полена, плетёный коврик.
 *
 * Крышки цилиндра у `cylinderUV` развёрнуты в метрах, как и всё остальное, и
 * для плит очага на срезе пня это верно. Для торца полена - нет: карта торца
 * задумана так, что её вписанный круг И ЕСТЬ торец (сердцевина в середине,
 * кора по кромке), а метровая развёртка при радиусе в пять сантиметров
 * показывала на торце четверть карты вокруг её угла - то есть кору и
 * изнанку. Здесь вершины с нормалью вдоль `axis` получают UV от 0 до 1 по
 * кругу радиуса `radius` вокруг оси: середина карты в середину торца.
 *
 * Считать после `cylinderUV` (она переписывает крышки) и до поворотов
 * геометрии: отбор по нормали держится на том, что ось круга - его
 * собственная.
 */
export declare function discUV(geo: THREE.BufferGeometry, radius: number, axis?: Along): void;
/** То же для плоскости: пол, потолок, накладка на стену. */
export declare function planeUV(geo: THREE.BufferGeometry, w: number, h: number, s?: number): void;
/**
 * То же для цилиндра: боковую поверхность разворачиваем по обхвату и высоте.
 *
 * Нужно ровно там, где эталон правил UV вручную у каждого бревна и полена.
 * `radius` берётся средний, если у цилиндра разные торцы.
 *
 * Крышки закрытого цилиндра разворачивать по обхвату нельзя: их штатные UV
 * идут веером от центра, и «обхватный» множитель растягивает рисунок кольцами.
 * Поэтому вершины крышек - те, у кого нормаль смотрит вдоль оси, |ny| > 0.9, -
 * получают планарную развёртку по своим x/z в метрах с тем же `s`. Так уже
 * работает эта функция в Winter Tower; поведение перенесено оттуда.
 *
 * Считать до `rotateX`/`rotateZ` самой геометрии: и метраж боковины, и отбор
 * крышек по нормали держатся на том, что ось цилиндра - его собственная Y.
 */
export declare function cylinderUV(geo: THREE.BufferGeometry, radius: number, height: number, s?: number): void;
/** Точка в пространстве как тройка чисел. */
export type P3 = [number, number, number];
/**
 * Произвольный четырёхугольник с UV в метрах - для скошенных граней, которым
 * коробка не годится: дымосборник, откос кровли, клин на изломе марша.
 *
 * Вершины идут по кругу (a, b, c, d). Меры берутся по двум рёбрам: ширина по
 * ab, высота по bc, и вся развёртка ложится прямоугольником |ab| на |bc|. Для
 * параллелограмма это точный метраж; у непараллелограмма рёбра cd и da
 * получают чужую длину, и рисунок вдоль них слегка тянется. Для нынешних
 * скосов перекос мал и терпим, но это допущение, а не свойство. Мерить по
 * габариту было бы хуже: он врёт тем сильнее, чем круче скос.
 *
 * Нормали считаются из порядка вершин, поэтому обход должен быть против часовой
 * стрелки со стороны, которую видно. Перепутанный обход даёт не «тёмную грань»,
 * а грань, которую видно насквозь при `side: FrontSide` - и ищут это обычно в
 * материале.
 */
export declare function quadGeometry(a: P3, b: P3, c: P3, d: P3, s?: number): THREE.BufferGeometry;
